-- NOSBLOC STAGING ONLY — NEVER APPLY TO THE PRODUCTION PROJECT.
-- Requires Edge secret NOSBLOC_STAGING_ENABLED=true. Discover, payments and payouts stay locked.
begin;
create table if not exists public.nosbloc_stg_runtime_config(id boolean primary key default true check(id),server_enabled boolean not null default true,discover_enabled boolean not null default false,payments_enabled boolean not null default false,payouts_enabled boolean not null default false,environment text not null default 'staging' check(environment='staging'),updated_at timestamptz not null default now());
insert into public.nosbloc_stg_runtime_config(id) values(true) on conflict(id) do nothing;
create table if not exists public.nosbloc_stg_creator_profiles(user_id uuid primary key references public.member_profiles(user_id) on delete cascade,passport_handle text not null,passport_country text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.nosbloc_stg_projects(project_id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.member_profiles(user_id) on delete cascade,client_project_id text not null,title text not null check(char_length(title) between 3 and 80),project_type text not null check(project_type in('world','game','story','fashion','music','shop')),template_key text not null,description text not null default '' check(char_length(description)<=2000),audience text not null default 'Tout public',payload jsonb not null default '{}'::jsonb check(jsonb_typeof(payload)='object' and pg_column_size(payload)<=1048576),rights_confirmed boolean not null default false,audience_confirmed boolean not null default false,moderation_confirmed boolean not null default false,status text not null default 'draft' check(status in('draft','review','approved','rejected','archived')),visibility text not null default 'private' check(visibility='private'),publication_locked boolean not null default true,discover_locked boolean not null default true,monetization_locked boolean not null default true,revision integer not null default 1 check(revision>0),review_version_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,client_project_id));
create table if not exists public.nosbloc_stg_project_members(project_id uuid not null references public.nosbloc_stg_projects(project_id) on delete cascade,member_key text not null,user_id uuid references public.member_profiles(user_id) on delete restrict,display_name text not null,role_name text not null,share_bps integer not null check(share_bps between 0 and 10000),membership_status text not null default 'draft' check(membership_status in('owner','draft','invited','accepted','declined','revoked')),invited_at timestamptz,accepted_at timestamptz,updated_at timestamptz not null default now(),primary key(project_id,member_key));
create table if not exists public.nosbloc_stg_invitations(invitation_id uuid primary key default gen_random_uuid(),project_id uuid not null references public.nosbloc_stg_projects(project_id) on delete cascade,member_key text not null,invited_user_id uuid not null references public.member_profiles(user_id) on delete cascade,invited_by uuid not null references public.member_profiles(user_id) on delete restrict,role_name text not null,share_bps integer not null check(share_bps between 0 and 10000),status text not null default 'invited' check(status in('invited','accepted','declined','revoked','expired')),idempotency_key uuid not null unique,created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval '14 days'),decided_at timestamptz,check(expires_at>created_at));
create unique index if not exists nosbloc_stg_one_open_invite on public.nosbloc_stg_invitations(project_id,invited_user_id) where status='invited';
create table if not exists public.nosbloc_stg_project_versions(version_id uuid primary key default gen_random_uuid(),project_id uuid not null references public.nosbloc_stg_projects(project_id) on delete cascade,version_no integer not null check(version_no>0),stage text not null check(stage in('checkpoint','review')),snapshot jsonb not null check(jsonb_typeof(snapshot)='object' and pg_column_size(snapshot)<=1048576),snapshot_hash text not null check(char_length(snapshot_hash)=64),note text not null default '' check(char_length(note)<=160),created_by uuid not null references public.member_profiles(user_id) on delete restrict,idempotency_key uuid not null unique,created_at timestamptz not null default now(),unique(project_id,version_no),unique(project_id,snapshot_hash));
do $$begin
  if not exists(
    select 1 from pg_constraint
    where conrelid='public.nosbloc_stg_projects'::regclass
      and conname='nosbloc_stg_review_version_fk'
  ) then
    alter table public.nosbloc_stg_projects
      add constraint nosbloc_stg_review_version_fk
      foreign key(review_version_id)
      references public.nosbloc_stg_project_versions(version_id)
      deferrable initially deferred;
  end if;
end$$;
create table if not exists public.nosbloc_stg_moderation_queue(case_id uuid primary key default gen_random_uuid(),project_id uuid not null references public.nosbloc_stg_projects(project_id) on delete cascade,version_id uuid not null references public.nosbloc_stg_project_versions(version_id) on delete restrict,status text not null default 'open' check(status in('open','review','approved','rejected')),assigned_to uuid references public.member_profiles(user_id) on delete restrict,decision_reason text not null default '' check(char_length(decision_reason)<=300),created_at timestamptz not null default now(),decided_at timestamptz,unique(version_id));
create table if not exists public.nosbloc_stg_audit_log(audit_id bigint generated always as identity primary key,actor_id uuid references public.member_profiles(user_id) on delete set null,project_id uuid references public.nosbloc_stg_projects(project_id) on delete set null,event_type text not null,event_id text not null,idempotency_key uuid unique,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.nosbloc_stg_block_mutation() returns trigger language plpgsql as $$begin raise exception 'immutable_staging_record';end$$;
drop trigger if exists nosbloc_stg_versions_immutable on public.nosbloc_stg_project_versions;create trigger nosbloc_stg_versions_immutable before update or delete on public.nosbloc_stg_project_versions for each row execute function public.nosbloc_stg_block_mutation();
drop trigger if exists nosbloc_stg_audit_immutable on public.nosbloc_stg_audit_log;create trigger nosbloc_stg_audit_immutable before update or delete on public.nosbloc_stg_audit_log for each row execute function public.nosbloc_stg_block_mutation();
create or replace function public.nosbloc_stg_guard() returns void language plpgsql security invoker as $$begin if not exists(select 1 from public.nosbloc_stg_runtime_config where id=true and server_enabled=true and environment='staging' and discover_enabled=false and payments_enabled=false and payouts_enabled=false) then raise exception 'staging_disabled';end if;end$$;
create or replace function public.nosbloc_stg_is_moderator(p_user uuid) returns boolean language sql stable security invoker as $$select exists(select 1 from public.member_profiles where user_id=p_user and public_verified=true and public_badge_key='director_founder')$$;
create or replace function public.nosbloc_stg_sync_project_server(p_user uuid,p_client_project text,p_payload jsonb,p_idempotency uuid) returns jsonb language plpgsql security invoker as $$declare v_project public.nosbloc_stg_projects;v_profile public.member_profiles;v_member jsonb;begin perform public.nosbloc_stg_guard();select * into v_profile from public.member_profiles where user_id=p_user;if not found then raise exception 'passport_required';end if;if p_client_project!~'^[A-Za-z0-9._:-]{3,100}$' or jsonb_typeof(p_payload)<>'object' or pg_column_size(p_payload)>1048576 then raise exception 'invalid_project';end if;insert into public.nosbloc_stg_creator_profiles(user_id,passport_handle,passport_country) values(p_user,v_profile.handle,v_profile.country) on conflict(user_id) do update set passport_handle=excluded.passport_handle,passport_country=excluded.passport_country,updated_at=now();insert into public.nosbloc_stg_projects(owner_id,client_project_id,title,project_type,template_key,description,audience,payload,rights_confirmed,audience_confirmed,moderation_confirmed) values(p_user,p_client_project,left(p_payload->>'title',80),p_payload->>'type',left(p_payload->>'template',100),left(coalesce(p_payload->>'description',''),2000),left(coalesce(p_payload->>'audience','Tout public'),60),p_payload,coalesce((p_payload#>>'{rights,contentOwned}')::boolean,false) and coalesce((p_payload#>>'{rights,thirdPartyLicensed}')::boolean,false),coalesce((p_payload#>>'{rights,audienceReviewed}')::boolean,false),coalesce((p_payload#>>'{safety,moderation}')::boolean,false)) on conflict(owner_id,client_project_id) do update set title=excluded.title,project_type=excluded.project_type,template_key=excluded.template_key,description=excluded.description,audience=excluded.audience,payload=excluded.payload,rights_confirmed=excluded.rights_confirmed,audience_confirmed=excluded.audience_confirmed,moderation_confirmed=excluded.moderation_confirmed,revision=nosbloc_stg_projects.revision+1,updated_at=now() where nosbloc_stg_projects.status in('draft','rejected') returning * into v_project;if v_project.project_id is null then raise exception 'project_locked';end if;for v_member in select * from jsonb_array_elements(coalesce(p_payload->'splits','[]')) loop insert into public.nosbloc_stg_project_members(project_id,member_key,user_id,display_name,role_name,share_bps,membership_status,accepted_at) values(v_project.project_id,left(v_member->>'memberKey',80),case when v_member->>'localStatus'='owner' then p_user else null end,left(v_member->>'name',50),left(v_member->>'role',50),greatest(0,least(10000,(v_member->>'shareBps')::integer)),case when v_member->>'localStatus'='owner' then 'owner' else 'draft' end,case when v_member->>'localStatus'='owner' then now() else null end) on conflict(project_id,member_key) do update set display_name=excluded.display_name,role_name=excluded.role_name,share_bps=excluded.share_bps,updated_at=now();end loop;delete from public.nosbloc_stg_project_members m where m.project_id=v_project.project_id and m.membership_status='draft' and not exists(select 1 from jsonb_array_elements(coalesce(p_payload->'splits','[]')) x where left(x->>'memberKey',80)=m.member_key);insert into public.nosbloc_stg_audit_log(actor_id,project_id,event_type,event_id,idempotency_key) values(p_user,v_project.project_id,'project_sync',v_project.revision::text,p_idempotency) on conflict(idempotency_key) do nothing;return jsonb_build_object('ok',true,'projectId',v_project.project_id,'revision',v_project.revision,'locks',jsonb_build_object('discover',true,'payments',true,'publication',true));end$$;
create or replace function public.nosbloc_stg_invite_server(p_user uuid,p_project uuid,p_member_key text,p_handle text,p_role text,p_share_bps integer,p_idempotency uuid) returns jsonb language plpgsql security invoker as $$declare v_recipient uuid;v_invite uuid;begin perform public.nosbloc_stg_guard();if not exists(select 1 from public.nosbloc_stg_projects where project_id=p_project and owner_id=p_user and status in('draft','rejected')) then raise exception 'owner_required';end if;select user_id into v_recipient from public.member_profiles where handle=lower(p_handle);if v_recipient is null or v_recipient=p_user then raise exception 'member_invalid';end if;insert into public.nosbloc_stg_invitations(project_id,member_key,invited_user_id,invited_by,role_name,share_bps,idempotency_key) values(p_project,left(p_member_key,80),v_recipient,p_user,left(p_role,50),greatest(0,least(10000,p_share_bps)),p_idempotency) returning invitation_id into v_invite;insert into public.nosbloc_stg_project_members(project_id,member_key,user_id,display_name,role_name,share_bps,membership_status,invited_at) select p_project,left(p_member_key,80),v_recipient,name,left(p_role,50),greatest(0,least(10000,p_share_bps)),'invited',now() from public.member_profiles where user_id=v_recipient on conflict(project_id,member_key) do update set user_id=excluded.user_id,display_name=excluded.display_name,role_name=excluded.role_name,share_bps=excluded.share_bps,membership_status='invited',invited_at=now(),accepted_at=null,updated_at=now();insert into public.nosbloc_stg_audit_log(actor_id,project_id,event_type,event_id,idempotency_key) values(p_user,p_project,'invitation_created',v_invite::text,p_idempotency) on conflict(idempotency_key) do nothing;return jsonb_build_object('ok',true,'invitationId',v_invite);end$$;
create or replace function public.nosbloc_stg_decide_invitation_server(p_user uuid,p_invitation uuid,p_accept boolean,p_idempotency uuid) returns jsonb language plpgsql security invoker as $$declare v public.nosbloc_stg_invitations;v_status text:=case when p_accept then 'accepted' else 'declined' end;begin perform public.nosbloc_stg_guard();select * into v from public.nosbloc_stg_invitations where invitation_id=p_invitation and invited_user_id=p_user and status='invited' and expires_at>now() for update;if not found then raise exception 'invitation_invalid';end if;update public.nosbloc_stg_invitations set status=v_status,decided_at=now() where invitation_id=p_invitation;update public.nosbloc_stg_project_members set membership_status=v_status,accepted_at=case when p_accept then now() else null end,updated_at=now() where project_id=v.project_id and member_key=v.member_key and user_id=p_user;insert into public.nosbloc_stg_audit_log(actor_id,project_id,event_type,event_id,idempotency_key) values(p_user,v.project_id,'invitation_'||v_status,p_invitation::text,p_idempotency) on conflict(idempotency_key) do nothing;return jsonb_build_object('ok',true,'status',v_status);end$$;
create or replace function public.nosbloc_stg_create_version_server(p_user uuid,p_project uuid,p_stage text,p_snapshot jsonb,p_snapshot_hash text,p_note text,p_idempotency uuid) returns jsonb language plpgsql security invoker as $$declare v_no integer;v_version uuid;v_case uuid;v_total integer;begin perform public.nosbloc_stg_guard();if not exists(select 1 from public.nosbloc_stg_projects where project_id=p_project and owner_id=p_user and status in('draft','rejected')) then raise exception 'owner_required';end if;if p_stage not in('checkpoint','review') or p_snapshot_hash!~'^[0-9a-f]{64}$' then raise exception 'version_invalid';end if;if p_stage='review' then select coalesce(sum(share_bps),0) into v_total from public.nosbloc_stg_project_members where project_id=p_project;if v_total<>10000 or exists(select 1 from public.nosbloc_stg_project_members where project_id=p_project and membership_status not in('owner','accepted')) then raise exception 'team_not_accepted';end if;if not exists(select 1 from public.nosbloc_stg_projects where project_id=p_project and rights_confirmed and audience_confirmed and moderation_confirmed) then raise exception 'rights_not_confirmed';end if;end if;perform 1 from public.nosbloc_stg_projects where project_id=p_project for update;select coalesce(max(version_no),0)+1 into v_no from public.nosbloc_stg_project_versions where project_id=p_project;insert into public.nosbloc_stg_project_versions(project_id,version_no,stage,snapshot,snapshot_hash,note,created_by,idempotency_key) values(p_project,v_no,p_stage,p_snapshot,p_snapshot_hash,left(coalesce(p_note,''),160),p_user,p_idempotency) returning version_id into v_version;if p_stage='review' then insert into public.nosbloc_stg_moderation_queue(project_id,version_id) values(p_project,v_version) returning case_id into v_case;update public.nosbloc_stg_projects set status='review',review_version_id=v_version,visibility='private',publication_locked=true,discover_locked=true,monetization_locked=true,updated_at=now() where project_id=p_project;end if;insert into public.nosbloc_stg_audit_log(actor_id,project_id,event_type,event_id,idempotency_key,metadata) values(p_user,p_project,'version_'||p_stage,v_version::text,p_idempotency,jsonb_build_object('version',v_no)) on conflict(idempotency_key) do nothing;return jsonb_build_object('ok',true,'versionId',v_version,'versionNo',v_no,'caseId',v_case,'private',true);end$$;
create or replace function public.nosbloc_stg_moderate_server(p_user uuid,p_case uuid,p_decision text,p_reason text,p_idempotency uuid) returns jsonb language plpgsql security invoker as $$declare v public.nosbloc_stg_moderation_queue;begin perform public.nosbloc_stg_guard();if not public.nosbloc_stg_is_moderator(p_user) then raise exception 'moderator_required';end if;if p_decision not in('approved','rejected') then raise exception 'decision_invalid';end if;select * into v from public.nosbloc_stg_moderation_queue where case_id=p_case and status in('open','review') for update;if not found then raise exception 'case_closed';end if;update public.nosbloc_stg_moderation_queue set status=p_decision,assigned_to=p_user,decision_reason=left(coalesce(p_reason,''),300),decided_at=now() where case_id=p_case;update public.nosbloc_stg_projects set status=p_decision,visibility='private',publication_locked=true,discover_locked=true,monetization_locked=true,updated_at=now() where project_id=v.project_id;insert into public.nosbloc_stg_audit_log(actor_id,project_id,event_type,event_id,idempotency_key) values(p_user,v.project_id,'moderation_'||p_decision,p_case::text,p_idempotency) on conflict(idempotency_key) do nothing;return jsonb_build_object('ok',true,'decision',p_decision,'private',true,'discoverLocked',true,'paymentsLocked',true);end$$;
create or replace function public.nosbloc_stg_snapshot_server(p_user uuid) returns jsonb language plpgsql security invoker as $$declare v_moderator boolean:=public.nosbloc_stg_is_moderator(p_user);begin perform public.nosbloc_stg_guard();return jsonb_build_object('ok',true,'isModerator',v_moderator,'projects',coalesce((select jsonb_agg(x order by x.updated_at desc) from(select p.*,mp.handle owner_handle from public.nosbloc_stg_projects p join public.member_profiles mp on mp.user_id=p.owner_id where p.owner_id=p_user or exists(select 1 from public.nosbloc_stg_project_members m where m.project_id=p.project_id and m.user_id=p_user and m.membership_status='accepted'))x),'[]'::jsonb),'incomingInvitations',coalesce((select jsonb_agg(x order by x.created_at desc) from(select i.*,p.title project_title from public.nosbloc_stg_invitations i join public.nosbloc_stg_projects p using(project_id) where i.invited_user_id=p_user and i.status='invited' and i.expires_at>now())x),'[]'::jsonb),'moderationQueue',case when v_moderator then coalesce((select jsonb_agg(x order by x.created_at) from(select q.*,p.title project_title,mp.handle owner_handle,v.version_no from public.nosbloc_stg_moderation_queue q join public.nosbloc_stg_projects p using(project_id) join public.member_profiles mp on mp.user_id=p.owner_id join public.nosbloc_stg_project_versions v on v.version_id=q.version_id where q.status in('open','review'))x),'[]'::jsonb) else '[]'::jsonb end);end$$;
do $$declare t text;begin foreach t in array array['nosbloc_stg_runtime_config','nosbloc_stg_creator_profiles','nosbloc_stg_projects','nosbloc_stg_project_members','nosbloc_stg_invitations','nosbloc_stg_project_versions','nosbloc_stg_moderation_queue','nosbloc_stg_audit_log'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on function public.nosbloc_stg_guard() from PUBLIC,anon,authenticated;
revoke all on function public.nosbloc_stg_is_moderator(uuid) from PUBLIC,anon,authenticated;
revoke all on function public.nosbloc_stg_sync_project_server(uuid,text,jsonb,uuid) from PUBLIC,anon,authenticated;
revoke all on function public.nosbloc_stg_invite_server(uuid,uuid,text,text,text,integer,uuid) from PUBLIC,anon,authenticated;
revoke all on function public.nosbloc_stg_decide_invitation_server(uuid,uuid,boolean,uuid) from PUBLIC,anon,authenticated;
revoke all on function public.nosbloc_stg_create_version_server(uuid,uuid,text,jsonb,text,text,uuid) from PUBLIC,anon,authenticated;
revoke all on function public.nosbloc_stg_moderate_server(uuid,uuid,text,text,uuid) from PUBLIC,anon,authenticated;
revoke all on function public.nosbloc_stg_snapshot_server(uuid) from PUBLIC,anon,authenticated;
grant execute on function public.nosbloc_stg_guard() to service_role;grant execute on function public.nosbloc_stg_is_moderator(uuid) to service_role;grant execute on function public.nosbloc_stg_sync_project_server(uuid,text,jsonb,uuid) to service_role;grant execute on function public.nosbloc_stg_invite_server(uuid,uuid,text,text,text,integer,uuid) to service_role;grant execute on function public.nosbloc_stg_decide_invitation_server(uuid,uuid,boolean,uuid) to service_role;grant execute on function public.nosbloc_stg_create_version_server(uuid,uuid,text,jsonb,text,text,uuid) to service_role;grant execute on function public.nosbloc_stg_moderate_server(uuid,uuid,text,text,uuid) to service_role;grant execute on function public.nosbloc_stg_snapshot_server(uuid) to service_role;
comment on table public.nosbloc_stg_runtime_config is 'Staging-only kill switches. Discover, payments and payouts must remain false.';
commit;
